#!/usr/bin/env python3
"""Build the early-record companion data. All prose is editorial, not scraped."""
import json, csv, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'parts'
talks=[]; items=[]; problems=[]; corrections=[]

def save():
    for name,data in [('talks',talks),('items',items),('problems',problems)]:
        (OUT/f'early_{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'early_corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary));save()

def item(record,pages,kind,title,notes,statement,cls,fate,refs=(),reconstruction='',literal='correct with missing hypotheses',match='partial',verification='read the result',development='annotated',problem='',confidence='high',status='',speaker=None):
    n=1+sum(x['record']==record for x in items)
    o=dict(id=f'1974-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of November 2026, '+(status or ('the stated reconstruction is a standard established result.' if cls in 'ABE' else 'the source does not determine a sufficiently precise claim for an open-problem status.')),literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth='',refs=list(refs),confidence=confidence)
    if speaker:o['speaker']=speaker
    items.append(o);save();return o['id']

def correction(page,place,reads,should,evidence,typ='faithful_error',applies='both'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ));save()

def problem(pid,title,statement,occurrences,status,refs):
    problems.append(dict(id=pid,title=title,statement=statement,occurrences=occurrences,status='As of November 2026, '+status,status_date='2026-11',refs=refs));save()

DMN='dubrovinmatveevnovikov1976nonlinear'
DN='dubrovinnovikov1974periodicity'
JETP='dubrovinnovikov1974periodic'
NV='novikov1974periodic'
MG='mingione2006regularity'
GJ='giusti1976boundary'
JV='milne1986jacobian'

talk(331,'1975-03-25','A. A. Kirillov','P000551','Diffeomorphism groups, gauge groups and exponential Hilbert space',r'The catalogue date is retained as supplied, but the manuscript heading on P000551 reads \(25/\mathrm{III}\text{-}74\). These notes repeat the material already indexed as 1973-331.1--4; the chronology of the catalogue entry is unresolved. The mathematical content consists of a representation-theoretic programme, the automorphism group of a principal bundle, and symmetric Fock space. P000550 and P000552 belong to adjacent talks, documented separately in the boundary audit.')
item(331,'P000551','remark','Representation programme for diffeomorphism and current groups',r'The groups \(G_1=\operatorname{Diff}M\) and \(G_2=H^M\), with smooth maps to a Lie group \(H\), are introduced in connection with describing representations.',r'For a smooth manifold \(M\) and Lie group \(H\), the current group \(C^\infty(M,H)\) has pointwise multiplication. No representation class, topology, irreducibility criterion or classification theorem is recorded.','F',r'\citet[title and abstract]{vershikgelfandgraev1975diffeomorphisms} is a relevant later programme, received 15 May 1975 and published in 1975; it does not identify an unrecorded Kirillov theorem. Earlier occurrence: 1973-331.1.',('vershikgelfandgraev1975diffeomorphisms',),literal='not determinable',match='thematic only',verification='publisher metadata checked',development='none',confidence='medium')
item(331,'P000551','construction','Automorphisms of a principal bundle and the gauge extension',r'For a principal \(H\)-bundle \(P\to M\), its automorphisms are said to project onto \(G_1\) with fibre \(G_2\).',r'There is an exact sequence \(1\to\operatorname{Gau}(P)\to\operatorname{Aut}(P)\to\operatorname{Diff}(M)_P\to1\), where \(\operatorname{Gau}(P)=\Gamma(M,\operatorname{Ad}P)\) and \(\operatorname{Diff}(M)_P=\{f:f^*P\simeq P\}\). For the trivial bundle, the kernel is \(C^\infty(M,H)\) and all base diffeomorphisms lift.','E',r'This is the standard bundle-automorphism construction; \citet[abstract and extension sequence]{wockel2007symmetry} formulates it for smooth symmetry groups (preprint December 2006; publication 2007). The construction itself is elementary and predates the talk. Earlier occurrence: 1973-331.2.',('wockel2007symmetry',),reconstruction=r'The bundle-preserving subgroup and the adjoint bundle are necessary additions; neither is specified in the shorthand.',literal='false as written',match='exact')
item(331,'P000551','construction','Symmetric Fock space',r'The exponential space is displayed as \(e^H=H_0\oplus H\oplus S^2H\oplus\cdots\), with one-dimensional \(H_0\).',r'For a complex Hilbert space \(H\), the bosonic Fock space is \(\mathcal F_s(H)=\bigoplus_{n=0}^{\infty}\operatorname{Sym}^nH\), the Hilbert direct sum with \(\operatorname{Sym}^0H=\mathbb C\).','E',r'\citet[\S4, pp.~370--373]{araki1970factorizable} uses the exponential Hilbert space in current-group representations; received June 1969, revised November 1969, published 1969/70. Earlier occurrence: 1973-331.3.',('araki1970factorizable',),literal='correct',match='exact')
item(331,'P000551','definition','Exponential vectors and factorial normalization',r'Tensor coordinates containing \(\xi^{\otimes n}/n!\) occur beside a norm with weights \(1/n!\). The tensor-product normalization is not stated.',r'With the usual Hilbert norms on symmetric tensor powers, \(\varepsilon(\xi)=(\xi^{\otimes n}/\sqrt{n!})_{n\ge0}\) satisfies \(\langle\varepsilon(\xi),\varepsilon(\eta)\rangle=e^{\langle\xi,\eta\rangle}\). An equivalent convention places \(1/n!\) in the sector norm and uses coordinates \(\xi^{\otimes n}\).','E',r'\citet[\S4]{araki1970factorizable} supplies the established exponential-space convention. The displayed factors cannot be combined without specifying a rescaling of each symmetric power. Earlier occurrence: 1973-331.4.',('araki1970factorizable',),reconstruction=r'The two consistent conventions above are an editorial normalization, not an assertion that one specific tensor norm was intended.',literal='not determinable',match='partial',confidence='medium')
correction('P000551','date of records 331--332','Catalogue: 25-Mar-75','Manuscript: 25/III-74; catalogue date retained in metadata','The scan heading unambiguously ends in 74; the same material occurs in the supplied previous-year index. Catalogue URLs could not be retrieved to resolve the discrepancy.','provenance')
correction('P000551','principal-bundle extension',r'\(\operatorname{Aut}(P)\to\operatorname{Diff}M\), kernel \(H^M\)',r'Image \(\operatorname{Diff}(M)_P\); kernel \(\Gamma(\operatorname{Ad}P)\)','The shorter formula is valid for a trivial bundle. In general a diffeomorphism lifts exactly when it preserves the bundle isomorphism class.')
correction('P000551','Fock-space normalization','Coordinates divided by n! and norm weighted by 1/n!','Specify the sector norm; standard coordinates use 1/sqrt(n!)','The handwritten factorials are retained; the ambiguity concerns conventions, not a demonstrable misread glyph.','ambiguity')

talk(332,'1975-03-25','B. M. Gurevich (as catalogued)','P000551','KdV by Whitham’s method: heading only',r'Only the heading \ru{Гуревич. О КдФ по методу Уизема} is recorded. The catalogue date 25 March 1975 conflicts with the manuscript date 25 March 1974, as in record 331. P000552--553 instead contain a separately dated spectral talk. The catalogue initials B.~M. are not silently replaced by A.~V., the author of the well-known Gurevich--Pitaevskii paper.')
item(332,'P000551','remark','An unrecorded account of Whitham’s method for KdV',r'The speaker heading announces KdV by Whitham\textquotesingle s method; no equation, theorem or argument follows.',r'No mathematically definite assertion can be recovered from this heading alone.','F',r'\citet[\S1]{gurevichpitaevskii1974shock} is a thematic comparator: submitted 3 April 1973, Russian publication August 1973, English translation February 1974. Its author is A.~V.~Gurevich, whereas this catalogue gives B.~M.; identity and contents are therefore not inferred. Earlier occurrence: 1973-332.1.',('gurevichpitaevskii1974shock',),literal='not determinable',match='thematic only',development='none',confidence='low')
correction('P000550-P000553','catalogue page ranges for records 331--332','Entire overlapping ranges assigned to the two records','Actual shared record content is on P000551','P000550 continues the preceding KdV discussion; P000552 is dated 1/IV-74 and begins the next spectral talk, continued on P000553.','provenance')

talk(334,'','','P000554','Academic-year heading: 1974',r'The year heading introduces the seminar\textquotesingle s thirty-second year. It has no separate mathematical assertion. The first dated meeting below it is 2 September 1974. The catalogue\textquotesingle s two-page range is a scan grouping, not a second lecture.',kind='heading')

talk(335,'1974-09-02','Enrico Giusti','P000554','Scalar regularity, elliptic systems and mean curvature',r'The introductory discussion distinguishes scalar regularity from the possible singularities of elliptic systems, then turns to prescribed mean curvature. The hypotheses are highly abbreviated. The detailed nonlinear-system example is deferred to record 341; the mean-curvature existence discussion continues in record 338.')
item(335,'P000554','theorem','Scalar Hölder regularity for measurable uniformly elliptic coefficients',r'The names Nash, De Giorgi and Moser accompany the assertion of regularity for one equation; the parenthesis mentions Hölder coefficients.',r'Let \(u\in W^{1,2}_{\mathrm{loc}}(\Omega)\) solve \(\operatorname{div}(A(x)Du)=0\), where \(A\) is bounded measurable and \(\nu|\xi|^2\le \xi^TA(x)\xi\), \(|A(x)|\le\Lambda\). Then \(u\) is locally Hölder continuous. Hölder continuity of \(A\) is unnecessary for this conclusion.','E',r'\citet[\S2, scalar regularity discussion]{mingione2006regularity} records the classical De Giorgi--Nash theory; the central results date from the 1950s, before this talk.','mingione2006regularity'.split(),reconstruction=r'The energy class, local conclusion and uniform bounds have been supplied explicitly.',match='exact')
item(335,'P000554','claim','Using linear theory in scalar nonlinear regularity',r'The scalar nonlinear situation is described as following the same regularity scheme.',r'For a uniformly elliptic quasilinear scalar equation, regularity can be bootstrapped once the solution and its gradient lie in a range where the coefficients and their required derivatives are controlled. Smoothness of the coefficient formula alone does not impose those bounds.','E',r'\citet[pp.~111--113]{giusti1982basic} explicitly distinguishes growth hypotheses, minimizers and merely stationary solutions. This is an expository methodological statement, not an unrestricted smoothness theorem.',('giusti1982basic',),reconstruction=r'No single nonlinear equation is specified. The statement records the valid method and its missing conditions, rather than choosing an unrecorded theorem.',match='partial',confidence='medium')
item(335,'P000554','claim','Failure of scalar regularity for elliptic systems',r'Giusti and Miranda are associated with an example of a nonregular solution despite analytic coefficients.',r'There are uniformly elliptic quasilinear systems with real-analytic dependence on the unknown and discontinuous energy-class weak solutions. One corrected concrete example for \(n=N\ge3\) is verified in the companion\textquotesingle s coefficient audit for record 341.','E',r'\citet[\S3.2, equations (3.3)--(3.5)]{mingione2006regularity} attributes the analytic-coefficient example to Giusti--Miranda (1968). The original 1968 paper was not retrieved; the later formula and the residual calculation are independently available.',(MG,),verification='indirect',match='partial',status='the phenomenon is established; the literal tensor later copied on P000565 needs a coefficient emendation.')
item(335,'P000554','theorem','Partial regularity and the dimension of the singular set',r'The singular set is stated to be closed and to have dimension less than \(n-2\).',r'For second-order quasilinear divergence systems with bounded uniformly elliptic coefficients continuous in \((x,u)\), standard partial regularity gives an open regular set. A quantitative Hausdorff-dimension improvement uses higher integrability and the appropriate small-energy regularity criterion; the notebook does not state these assumptions or distinguish regularity of \(u\) from regularity of \(Du\).','E',r'\citet[Theorems 1--2]{giusti1969partial} is a relevant pre-talk source, received July 1968 and published 1969. The opened scan\textquotesingle s formula extraction was insufficient to verify the exact strict dimension bound in its full hypotheses; the numerical bound here is therefore only a partial match.',('giusti1969partial',MG),reconstruction=r'The target is partial regularity of the weak solution, not a universal bound for every nonlinear elliptic system.',verification='indirect',match='partial',confidence='medium',status='partial regularity is classical, but this audit has not verified the notebook\textquotesingle s exact strict dimension statement under only the hypotheses written there.')
item(335,'P000554','definition','Mean curvature of a graph and a size obstruction',r'The graph \(x\mapsto u(x)\) is assigned mean curvature \(n^{-1}\operatorname{div}(Du/\sqrt{1+|Du|^2})\); prescribed curvature cannot be arbitrarily large.',r'For an oriented \(C^2\) graph over \(\Omega\subset\mathbb R^n\), the signed average principal curvature is \(n^{-1}\operatorname{div}(Du/\sqrt{1+|Du|^2})\), up to orientation. Integrating the divergence over a subdomain bounds total prescribed curvature by boundary area.','E',r'\citet[\S1B]{giusti1976boundary} develops the associated perimeter condition. The flux obstruction is elementary and already part of the pre-1974 mean-curvature existence theory; record 338 gives its explicit form.',(GJ,),match='exact')
correction('P000554','Nash--De Giorgi--Moser parenthesis','Hölder coefficients','Bounded measurable, uniformly elliptic coefficients suffice for Hölder continuity of energy weak solutions','This separates the Hölder regularity of the solution from an unnecessary hypothesis on the coefficients.','ambiguity')

# Additional records are appended below; save() is called after every item.
talk(336,'1974-09-02','S. P. Novikov; B. A. Dubrovin','P000554-P000556','Algebraic tori, commuting Hamiltonians and finite-gap spectra',r'The talk links Jacobians of hyperelliptic curves to the stationary KdV hierarchy. It contains an explicit genus-two Hamiltonian construction, the Abel map, and the spectral interpretation of Bloch functions. The algebraic statements require a polarization, a nonsingular spectral curve and compactification of affine levels. Two polynomial coefficients and the claim that the Abel map is globally an isomorphism require separate scrutiny. The broad question about describing all tori does not specify a modern moduli problem.')
item(336,'P000554','definition','Complex tori and algebraic tori',r'A torus is written \(\mathbb C^n/\Lambda\), where \(\Lambda\) has a basis of \(2n\) vectors; algebraic tori are called abelian varieties.',r'A complex torus is \(\mathbb C^g/\Lambda\) for a discrete lattice of rank \(2g\) spanning the real vector space. It is an abelian variety precisely when it is projective, equivalently when it admits a positive Riemann form. Here “algebraic torus” means a projective complex torus, not the affine group \((\mathbb C^*)^g\).','E',r'\citet[complex tori and Riemann forms]{milne2008abelian} gives the classical criterion. The terminology in these notes is historical and should not be confused with an algebraic group torus.',('milne2008abelian',),match='exact')
item(336,'P000554','question','The unspecified problem of describing all tori',r'Novikov asks how to describe all tori, noting that dimension two is already nontrivial.',r'The notebook does not say whether tori are polarized, whether isomorphism or isogeny is intended, or whether the aim is a parameter space, a Jacobian criterion or explicit functions. No unique definite problem follows.','F',r'The marked hyperelliptic-Jacobian construction of \citet[\S4]{dubrovinnovikov1974periodicity} is a precise nearby result, submitted 3 June 1974 and published later in 1974. It does not settle every possible interpretation of the question.',(DN,),literal='not determinable',match='thematic only',development='none',confidence='low')
item(336,'P000554','construction','Hyperelliptic curves and their holomorphic differentials',r'The curve \(y^2=P_{2g+1}(x)\) is used with the forms \(x^kdx/y\).',r'If \(P_{2g+1}\in\mathbb C[x]\) has distinct roots, the smooth projective compactification of \(y^2=P_{2g+1}(x)\) has genus \(g\); \(x^kdx/y\), \(0\le k\le g-1\), is a basis of holomorphic differentials. Repeated roots require normalization and can lower the genus.','E',r'This classical construction is the input to \citet[\S3]{dubrovinnovikov1974periodicity}, not a new assertion of that paper.',(DN,),reconstruction=r'Square-freeness, compactification and the index range have been made explicit.',match='exact')
item(336,'P000554','construction','The Jacobian and the missing Hodge quotient',r'The Jacobian is written \(H^1(R,\mathbb C)/H^1(R,\mathbb Z)\).',r'For a compact Riemann surface \(R\) of genus \(g\), \(J(R)=H^0(R,\Omega_R^1)^*/H_1(R,\mathbb Z)\), with the lattice embedded by integration. Equivalently, \(J(R)=H^1(R,\mathbb C)/(F^1H^1(R,\mathbb C)+H^1(R,\mathbb Z))\). The literal quotient omits a complex \(g\)-dimensional Hodge subspace.','E',r'\citet[\S2, analytic description]{milne1986jacobian} gives the period construction. The omission is mathematical: the literal numerator has complex dimension \(2g\) and its rank-\(2g\) lattice does not give the compact Jacobian.',(JV,),literal='false as written',match='exact')
item(336,'P000554','construction','Period matrices and the moduli diagram',r'A diagram relates curves, tori, periods and a domain of matrices.',r'After a symplectic marking and normalization, a principally polarized complex abelian variety is represented by a symmetric matrix \(\tau\) with \(\operatorname{Im}\tau>0\). Changing the marking acts by \(\operatorname{Sp}_{2g}(\mathbb Z)\). The resulting quotient describes principally polarized abelian varieties; the period map from curves lands in the Jacobian locus.','E',r'\citet[polarizations and moduli]{milne2008abelian} supplies the standard setting. The diagram does not specify a level structure or a fine moduli space, and its arrows are not treated as unqualified isomorphisms.',('milne2008abelian',),reconstruction=r'Principal polarization and marking are editorial additions required to identify the matrix domain.',match='partial',confidence='medium')
item(336,'P000555','construction','A genus-two polynomial Hamiltonian pair and its corrected quartic coefficient',r'The notes give \(J_1=p_1p_2+V\), \(J_2=p_1^2-2q_1p_1p_2+2(q_2-c)p_2^2+D\), claiming \(\{J_1,J_2\}=0\), where the quartic term of \(V\) is \(-5q_1^4/2\).',r'Identify \(c=c_1,d=d_1\) and put \[V_a=-\tfrac12q_2^2-\tfrac52q_1^2q_2-aq_1^4+cq_1^2-dq_1,\quad D=q_1^5+2cq_1^3+dq_1^2-4q_1q_2^2+4cq_1q_2-2dq_2.\] For \(\{f,g\}=\sum_i(f_{q_i}g_{p_i}-f_{p_i}g_{q_i})\), direct calculation gives \(\{J_1,J_2\}=(8a-5)q_1^3(q_1p_2-p_1)\). Thus the copied coefficient \(a=5/2\) fails, while \(a=5/8\) works.','A',r'The coefficient \(5/8\) agrees with \citet[\S4]{dubrovinnovikov1974periodicity}, received 3 June 1974, publication 1974. The exact residual and a separate coefficient calculation are supplied in the audit; no novel integrable system is claimed.',(DN,),reconstruction=r'The identification of the differently subscripted parameters is explicit. The replacement concerns the last quartic coefficient only.',literal='false as written',match='exact',development='annotated',status='the corrected classical commuting pair is established; the printed notebook pair is not in involution.')
item(336,'P000555','claim','Commuting Hamiltonian vector fields',r'The two Hamiltonian fields are asserted to commute.',r'On a symplectic manifold, \([X_f,X_g]=\pm X_{\{f,g\}}\), with sign determined by convention. Consequently the corrected pair in item 1974-336.6 has commuting Hamiltonian fields. The uncorrected pair generally does not.','E',r'This is the standard Hamiltonian identity used in \citet[\S2]{dubrovinnovikov1974periodicity}. The application is contingent on the coefficient correction, not a second independent assertion of involution.',(DN,),literal='false as written',match='exact')
item(336,'P000555','theorem','Common levels as open parts of abelian varieties',r'The common levels \(J_1,J_2=\mathrm{constant}\) and flow orbits are called tori or abelian varieties.',r'For the corrected genus-two stationary-KdV system and generic constants giving a nonsingular spectral curve, the affine common level is identified with a Zariski-open part of its Jacobian. The complete abelian surface is obtained by compactification. Compact nonsingular real components support the real torus dynamics; arbitrary complex affine levels are not compact tori.','A',r'\citet[\S\S2--4]{dubrovinnovikov1974periodicity} and \citet[Ch.~II, \S4]{dubrovinmatveevnovikov1976nonlinear} give the finite-gap algebraic-integrability construction (1974 result; 1976 synthesis).',(DN,DMN),reconstruction=r'Genericity and compactification are necessary. Singular spectral curves require a separate degeneration theory.',literal='correct with missing hypotheses',match='exact')
item(336,'P000555','theorem','Rational parametrization of the marked universal hyperelliptic Jacobian',r'The collection of all the preceding tori is said to be unirational.',r'The precise nearby construction concerns a total family of hyperelliptic Jacobians, with a distinguished branch point and the coordinate/marking normalizations used in its polynomial model. It is a rational total parameter variety in that formulation, hence gives a unirational family after forgetting the finite marking. This does not make any fixed positive-dimensional complex abelian variety unirational.','A',r'\citet[\S4, theorem]{dubrovinnovikov1974periodicity} states rationality of the marked total variety; the manuscript is its abbreviated geometric consequence.',(DN,),reconstruction=r'The family and its marking have been supplied from the matching result; an arbitrary fine-moduli interpretation is not asserted.',match='partial',confidence='medium')
item(336,'P000555','construction','The spectral quintic and a parameter-normalization discrepancy',r'The curve is written \[y^2=E^5+\tfrac c4E^3-\tfrac d{16}E^2+(\tfrac{J_1}{32}+\tfrac{c^2}{4})E+\tfrac{J_2}{256}+\tfrac{cd}{128}.\]',r'The coefficient multiplying \(E\) must be checked against the chosen Hamiltonian normalization. Translating the published parameters \(c_2,c_1\) by \(c=8c_2,d=c_1\) gives \(J_1/32+c^2/64\), with the other displayed coefficients unchanged. The notebook\textquotesingle s \(c^2/4\) therefore does not match that simultaneous parameter identification.', 'A',r'\citet[\S4, final spectral equation]{dubrovinnovikov1974periodicity} provides the comparison. Its available author-hosted transcription also has apparent typographic omissions in \(J_2\), so the spectral correction is recorded as a normalization discrepancy, not a recovered glyph.',(DN,),reconstruction=r'The proposed \(c^2/64\) is a reconstruction from the published normalization; the notebook does not give the Lax matrix needed for an independent identification of its spectral coordinate.',literal='not determinable',match='partial',confidence='medium',status='the genus-two spectral construction is known; the precise literal coefficient remains a documented normalization discrepancy.')
item(336,'P000555','construction','Abel’s map from a symmetric power',r'The map \(S^gR\to J(R)\), given by sums of integrals of holomorphic differentials from a base point, is called an isomorphism.',r'For a smooth projective complex curve of genus \(g\), \(D\mapsto[D-gQ]\) maps \(\operatorname{Sym}^gR\) surjectively and birationally to \(J(R)\). Its fibre over \([D-gQ]\) is the complete linear system \(|D|\). Thus it is an isomorphism on the nonspecial locus, but generally not globally: in genus two the hyperelliptic pencil gives a positive-dimensional fibre.','E',r'\citet[Theorem~5.1 and the preceding fibre description]{milne1986jacobian} states the classical result. The source is a 2021 corrected version of the 1986 chapter; the mathematical theorem long predates this lecture.',(JV,),literal='false as written',match='exact')
item(336,'P000555','definition','Normalized Bloch solutions and the unit multiplier condition',r'For \(L=-d^2/dx^2+u\), the notes impose \(\Psi(x+T)=\lambda\Psi(x)\), \(|\lambda|=1\), \(\lambda=e^{ip}\), and \(\Psi(x_0)=1\).',r'For a real smooth \(T\)-periodic potential, Floquet solutions satisfy \(\Psi(x+T,E)=\lambda(E)\Psi(x,E)\). The condition \(|\lambda|=1\) characterizes real spectral bands; it is not true in open gaps. Normalization at \(x_0\) is meromorphic in the spectral point and fails as an ordinary finite value at its pole divisor.','E',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} sets out the standard Floquet normalization used in the new finite-gap construction.',(DMN,),match='exact')
item(336,'P000555','remark','The almost-periodic completeness warning',r'For almost-periodic potentials the collection of such eigenfunctions is said not to form a complete system.',r'An almost-periodic function need not have a period \(T\), so the preceding monodromy eigenvalue equation does not define a general Bloch basis. No function space, spectral measure or notion of completeness is specified here.','F',r'\citet[\S3]{dubrovinnovikov1974periodicity} distinguishes the periodic case from an imposed meromorphic finite-gap condition in the conditionally periodic case. This does not identify an exact completeness counterexample.',(DN,),literal='not determinable',match='thematic only',development='none',confidence='low')
item(336,'P000555','construction','The two-sheeted spectral surface and its genus',r'Two eigenfunctions lead to a two-sheeted surface branched at spectral endpoints, described as having infinite genus.',r'The normalized Bloch functions for a real periodic Schrödinger operator are naturally considered on a two-sheeted spectral surface. Open-gap endpoints are branch points; closed gaps give removable double points after normalization. Infinitely many open gaps give an infinite-genus surface. With \(g\) open gaps, the compact finite-gap model is \(y^2=\prod_{j=0}^{2g}(E-E_j)\), of genus \(g\).','E',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} distinguishes the general periodic surface from its finite-gap algebraic specialization.',(DMN,),reconstruction=r'The qualifier “infinitely many open gaps” is necessary; periodicity alone does not imply infinite genus.',match='exact')
item(336,'P000556','theorem','The finite-gap isospectral family and its Jacobian',r'The set of potentials with the same spectrum is identified with the Jacobian of the spectral surface.',r'Fix a real nonsingular finite-gap spectrum with \(g\) open gaps and admissible real divisor data. The corresponding smooth real isospectral family is a real \(g\)-torus in the complex Jacobian. The complex algebraic construction is described on an open Jacobian chart and its compactification. Infinite-gap spectra require additional analytic hypotheses and do not give this finite-dimensional statement.','A',r'\citet[\S3]{dubrovinnovikov1974periodicity} gives the finite-gap identification and linearized flows; publication followed the September lecture in 1974, with receipt on 3 June 1974.',(DN,),reconstruction=r'The finite-gap and real-admissibility conditions are made explicit.',match='exact')
correction('P000554','Jacobian quotient',r'\(H^1(R,\mathbb C)/H^1(R,\mathbb Z)\)',r'\(H^1(R,\mathbb C)/(F^1H^1+H^1(R,\mathbb Z))\)','The scan genuinely gives the shorter quotient. Its complex dimension and noncompactness are incompatible with the Jacobian.')
correction('P000555','quartic term in V',r'\(-5q_1^4/2\)',r'\(-5q_1^4/8\)',r'The literal bracket equals \(15q_1^3(q_1p_2-p_1)\). The corrected coefficient gives zero and agrees with Dubrovin--Novikov (1974), section 4.')
correction('P000555','parameters in Hamiltonian pair','c,d and c1,d1','Identify c=c1 and d=d1 for the displayed commuting-pair reconstruction','The notebook changes parameter labels without declaring the identification.','ambiguity')
correction('P000555','coefficient of E in spectral quintic',r'\(J_1/32+c_1^2/4\)',r'Published normalization suggests \(J_1/32+c_1^2/64\)','Under c=8c2,d=c1 in the 1974 published formula, all the other coefficients match. The remaining discrepancy is retained as a normalization reconstruction.','ambiguity')
correction('P000555','Abel theorem','isomorphism','birational map; isomorphism on the nonspecial locus','The fibre over a divisor class is its complete linear system; special effective divisors give positive-dimensional fibres.')
correction('P000555-P000556','torus and Jacobian identification','All common affine levels are abelian varieties; all isospectral sets are Jacobians','Generic affine levels are open parts of compact Jacobians; the finite-gap real isospectral family is a real torus','Affine levels are not compact; the finite-dimensional theorem requires a nonsingular finite-gap curve.')

talk(337,'1974-09-09','Czesław Bessaga; I. M. Gelfand (intervention)','P000556','Z-sets, infinite-dimensional spaces and the space of rays',r'The notes introduce negligible subsets of the Hilbert cube and the extension theorem for their homeomorphisms. They also mention the topological classification of separable infinite-dimensional Fréchet spaces. Gelfand\textquotesingle s space-of-rays example has an exact published antecedent in 1967. Two literal assertions need correction: the pseudoboundary is a countable union of Z-sets, and a maximal such union cannot mean maximal by ordinary inclusion.')
item(337,'P000556','definition','Z-sets defined by approximation of Hilbert-cube maps',r'A closed subset \(A\) of a complete metric space \(X\) is called a Z-set if continuous maps of the Hilbert cube can be approximated by maps missing \(A\).',r'For a metric space \(X\), a closed subset \(A\subset X\) is a Z-set in the stated sense if for every continuous \(f:Q\to X\) and every \(\varepsilon>0\) there is continuous \(g:Q\to X\setminus A\) with \(\sup_Qd(f,g)<\varepsilon\), where \(Q=[-1,1]^{\mathbb N}\).','E',r'\citet[introduction, pp.~281--282]{andersonchapman1971extending} recalls the established negligible-set theory and its equivalent formulations in Hilbert-cube manifolds. The ambient-space hypotheses matter when moving between those formulations.',('andersonchapman1971extending',),literal='correct',match='exact')
item(337,'P000556','claim','The pseudoboundary of the Hilbert cube',r'For \(Q=[-1,1]^{\mathbb N}\) and \(P=(-1,1)^{\mathbb N}\), the notes call \(Q\setminus P\) a Z-set.',r'The pseudoboundary is \(\bigcup_{j\ge1}\{x\in Q:|x_j|=1\}\), a countable union of closed Z-sets. It is dense and not closed in \(Q\), so it is not itself a Z-set under the preceding definition. Each coordinate face can be avoided by an arbitrarily small inward change in that coordinate.','E',r'The distinction is part of the Hilbert-cube setting of \citet[pp.~281--282]{andersonchapman1971extending}; the correction also follows immediately from the definition copied in the notes.',('andersonchapman1971extending',),literal='false as written',match='partial',status='the pseudoboundary is a sigma-Z-set, and the literal Z-set claim is false.')
item(337,'P000556','theorem','Z-set unknotting in the Hilbert cube',r'A homeomorphism between two Z-sets extends to a homeomorphism of the surrounding cube.',r'If \(A,B\) are closed Z-sets in the Hilbert cube \(Q\), every homeomorphism \(h:A\to B\) extends to a homeomorphism \(H:Q\to Q\).','E',r'\citet[Theorem~4 and corollary, pp.~37--38]{anderson1967special} gives the extension theorem in its equivalent deficient-set formulation; \citet[introduction]{andersonchapman1971extending} explicitly recalls Z-set unknotting. Both precede the talk.',('anderson1967special','andersonchapman1971extending'),reconstruction=r'The ambient Hilbert cube is essential; the preceding definition for arbitrary complete metric spaces does not make the extension assertion true there.',match='exact')
item(337,'P000556','definition','Countable unions of Z-sets',r'A \(Z_\sigma\)-set is introduced as a countable union of Z-sets.',r'A sigma-Z-set in \(X\) is a set \(A=\bigcup_{m\ge1}A_m\) with each \(A_m\) a closed Z-set in \(X\). The union need not be closed.','E',r'This is standard negligible-set terminology in the infinite-dimensional topology discussed by \citet[pp.~31--38]{anderson1967special}. The pseudoboundary is the preceding concrete example.',('anderson1967special',),literal='correct',match='exact')
item(337,'P000556','claim','The ambiguous maximal sigma-Z-set assertion',r'The notes say that a maximal \(Z_\sigma\)-set exists.',r'If maximal means maximal by inclusion among sigma-Z-subsets of \(Q\), the claim is false. Every Z-set is nowhere dense, so a sigma-Z-set is meagre and is not \(Q\). Any missing point is itself a Z-set, and adjoining it gives a strictly larger sigma-Z-set. A universal or absorbing-set meaning would require an additional definition.','F',r'The literal obstruction follows from the Baire theorem and the preceding definition. Searches in the opened Anderson and Anderson--Chapman sources did not identify a theorem with the unqualified maximality stated here.',('anderson1967special','andersonchapman1971extending'),literal='false as written',match='none found',verification='unresolved lead',confidence='low',status='inclusion-maximality is refuted; an intended absorbing or universal notion is not recoverable from this sentence.')
item(337,'P000556','claim','Every continuous real function on the ray space is constant',r'Gelfand considers rays in the space of real sequences and says that every continuous function on the quotient is constant.',r'Let \(X=\mathbb R^{\mathbb N}\) have its product topology and let \(S=(X\setminus\{0\})/\mathbb R_{>0}\) be the quotient by positive scalar multiplication. Every continuous \(S\to\mathbb R\) is constant. Equivalently, every continuous degree-zero homogeneous real function on \(X\setminus\{0\}\) is constant.','E',r'\citet[introduction, Russian p.~34]{gelfandfuchs1967topology} states this exact example; received July 1967, published 1967. The space is described there as Hausdorff but nonregular, not as a non-Hausdorff quotient. Earlier occurrence: 1967-132.7.',('gelfandfuchs1967topology',),reconstruction=r'The product topology and positive scaling are essential. A normed-space unit sphere gives a different quotient.',literal='correct with missing hypotheses',match='exact',problem='GP-1974-01',speaker='I. M. Gelfand')
item(337,'P000556','theorem','Homeomorphism type of infinite-dimensional separable Fréchet spaces',r'All separable Fréchet spaces are said to be homeomorphic.',r'All infinite-dimensional separable real Fréchet spaces are homeomorphic to separable Hilbert space. Finite-dimensional spaces are excluded: their topological dimensions distinguish them from one another and from the infinite-dimensional case.','E',r'\citet[p.~31]{anderson1967special} explicitly summarizes the already established Anderson--Kadec and related results. The 1966 symposium paper appeared in 1967, before this talk.',('anderson1967special',),literal='false as written',match='exact')
problem('GP-1974-01','Continuous functions on the product-sequence ray space',r'For \(S=(\mathbb R^{\mathbb N}\setminus\{0\})/\mathbb R_{>0}\) with the quotient of the product topology, is every continuous real function constant?', ['1967-132.7','1974-337.6'],r'yes; the exact example was published in 1967 by \citet[introduction]{gelfandfuchs1967topology}. The earlier occurrence had no separate exact problem identifier. This is a settled explanatory example, not a new open problem.', ['gelfandfuchs1967topology'])
correction('P000556','Hilbert-cube pseudoboundary',r'\(Q\setminus P\) is a Z-set',r'\(Q\setminus P\) is a sigma-Z-set','It is a dense nonclosed union of the closed coordinate faces. The source definition explicitly requires a Z-set to be closed.')
correction('P000556','maximal negligible set',r'A maximal \(Z_\sigma\)-set exists','No inclusion-maximal sigma-Z-subset of Q exists; intended universal meaning unspecified','Baire category gives a missing point, and adjoining that singleton preserves the sigma-Z property.','ambiguity')
correction('P000556','Fréchet-space classification','All separable Fréchet spaces are homeomorphic','All infinite-dimensional separable Fréchet spaces are homeomorphic','Finite-dimensional real spaces have distinct topological dimensions. Anderson (1967), p. 31, states the infinite-dimensional qualification.')

talk(338,'1974-09-09','Enrico Giusti','P000556-P000558','Prescribed mean curvature, boundary obstructions and BV relaxation',r'The lecture first gives elementary failures of classical solvability, including a radial annulus and a one-dimensional solution with infinite slope. It then builds the variational setting in bounded variation: dual definitions of total variation and area, lower semicontinuity, compactness and a boundary mismatch term. The sign of the volume potential conflicts with the earlier PDE convention. The cutoff-minimization question is meaningful only after coercivity and the boundary class are specified.')
item(338,'P000556','problem','The prescribed-mean-curvature Dirichlet equation',r'The equation is \(\operatorname{div}(Du/\sqrt{1+|Du|^2})=-H(x,u)\), with \(u=\phi\) on the boundary; \(H=0\) is the minimal-surface case.',r'Given a bounded domain \(\Omega\), boundary data \(\phi\) and prescribed function \(H\), seek an appropriately defined solution of the displayed graph equation with the stated boundary trace. Classical, weak Sobolev and relaxed BV solutions are different formulations; none exists for arbitrary data without additional conditions.','E',r'\citet[introduction and \S1]{giusti1976boundary} treats the generalized Dirichlet formulation and recalls the earlier work on existence. The lecture\textquotesingle s examples establish why the solution class must be stated.',(GJ,),match='exact')
item(338,'P000556-P000557','construction','A radial annulus and the maximal catenoid height',r'On \(1<|x|<2\subset\mathbb R^2\), radial minimal graphs have inner value \(M\) and outer value zero; beyond \(M_0\) no solution exists.',r'For \(0\le c\le1\), the radial solutions are \[u_c(r)=c\log\frac{2+\sqrt{4-c^2}}{r+\sqrt{r^2-c^2}}.\] Their heights increase to \(M_0=\log(2+\sqrt3)\). There is no \(C^2(\Omega)\cap C^0(\overline\Omega)\) minimal graph with these boundary values if \(M>M_0\): comparison gives uniqueness, rotation invariance forces radiality, and \(ru^{\prime}/\sqrt{1+(u^{\prime})^2}=-c\) forces \(c\le1\). At equality the inner-boundary slope is infinite.','E',r'This is an explicit catenoid calculation illustrating the classical-versus-generalized distinction in \citet[introduction]{giusti1976boundary}. Its exact formula and threshold follow directly by integrating the radial equation.',(GJ,),reconstruction=r'The solution class and the equality case are editorially explicit; \(C^1\) regularity up to the inner boundary fails at \(c=1\).',match='thematic only')
item(338,'P000557','remark','Soap-film diagrams as a geometric illustration',r'Drawings show a film lifted with a rod and a film spanning wire rings, accompanying an experimental check of loss of graph solvability.',r'The drawings illustrate the distinction between a single-valued graph over an annulus and a general spanning surface. They specify no surface functional, stability criterion, contact-angle condition or exact transition height for the physical experiment.','F',r'The neighbouring radial calculation is identifiable, but no precise theorem about the drawn experiment is recorded. The general variational background in \citet[introduction]{giusti1976boundary} is thematic only.',(GJ,),literal='not determinable',match='thematic only',development='none',confidence='low')
item(338,'P000557','construction','A continuous prescribed curvature with an infinite-slope solution',r'The example \(u(x)=3x^{1/3}\), \(-1<x<1\), is nondifferentiable at zero although the derivative of its curvature flux is continuous.',r'Using the real cube root, \(u\in W^{1,1}(-1,1)\) and \(u^{\prime}=|x|^{-2/3}\) almost everywhere. Its flux is \(q=(1+|x|^{4/3})^{-1/2}\), with \(q^{\prime}=-(2/3)\sqrt[3]{x}(1+|x|^{4/3})^{-3/2}\), a continuous function. Thus a weak graph solution may have continuous right-hand side without finite slope. It is not in \(W^{1,2}\).','E',r'The assertion is verified by direct differentiation and integrability at zero; it illustrates the degeneracy explained by \citet[\S1]{giusti1976boundary}. No exact published formula match was found.',(GJ,),literal='correct',match='thematic only')
item(338,'P000557','claim','Raising one endpoint beyond the possible flux',r'After \(u(-1)=-3,u(1)=3\), the notes change to \(u(-1)=3,u(1)=3+A\) but integrate from the value \(-3\).',r'For the fixed right-hand side of item 1974-338.4, retain \(v(-1)=-3\). Any admissible flux is \(q_v=q+C\). Since \(q(0)=1\) and \(|q_v|\le1\), necessarily \(C\le0\); monotonicity of \(s/\sqrt{1+s^2}\) gives \(v^{\prime}\le |x|^{-2/3}\). Therefore \(v(1)\le3\), and data \(v(1)=3+A\), \(A>0\), are impossible.','E',r'This is the elementary one-dimensional obstruction adjacent to the explicit example. The general perimeter obstruction is treated by \citet[\S1B]{giusti1976boundary}.', (GJ,),reconstruction=r'The left endpoint is restored to \(-3\), and the omitted integration constant is included. The equality flux corresponds to a weak solution with infinite slope.',literal='false as written',match='thematic only')
item(338,'P000557','method','The area-plus-potential functional and its Euler equation',r'The functional is \(\mathcal F(u)=\int_\Omega\sqrt{1+|Du|^2}+\int_\Omega\lambda(x,u)\), with \(\lambda_t=H\).',r'For smooth admissible variations with fixed boundary values, the displayed plus sign gives \(-\operatorname{div}(Du/\sqrt{1+|Du|^2})+H(x,u)=0\), hence \(\operatorname{div}(Du/\sqrt{1+|Du|^2})=H(x,u)\). To match the earlier equation with \(-H\), use \(-\lambda\) or redefine the sign of \(H\).','E',r'The first variation is immediate. \citet[\S1]{giusti1976boundary} uses a consistent area-plus-volume convention; the notebook switches conventions without warning.',(GJ,),literal='false as written',match='exact')
item(338,'P000557','question','Removing the gradient cutoff in variational minimization',r'A minimum is asserted under \(|Du|\le K\); then the notes ask whether the minimizers \(u_K\) converge as \(K\to\infty\).',r'On a bounded Lipschitz domain with nonempty fixed-trace admissible class, a fixed uniform gradient bound and suitable continuity of the potential give a direct-method minimum. Removing the bound requires a uniform BV and \(L^1\) estimate. It is false without coercivity: if \(H=h>0\) is sufficiently large and \(w\ge0\) has zero trace with \(h\int w>\int|Dw|\), then \(\mathcal F(-tw)\to-\infty\). Under a coercive relaxed functional, subsequences converge in \(L^1\) to BV minimizers, which need not retain the classical boundary values.','E',r'\citet[introduction and existence hypotheses]{giusti1976boundary} explains the BV setting and necessary size restrictions. The unqualified convergence question has no affirmative answer; the positive compactness argument is supplied by the subsequent items.',(GJ,),reconstruction=r'The coercivity and boundary assumptions are not present in the question. The elementary large-force counterexample shows why they cannot be omitted.',literal='correct with missing hypotheses',match='partial',confidence='medium',status='the conditional BV approach is classical; unconditional convergence is false and no separate open problem is inferred.')
item(338,'P000557','claim','A necessary flux-perimeter inequality',r'For a Lipschitz solution and \(A\subset\Omega\), the notes bound \(|\int_AH|\) by \((1-\varepsilon_0)\mathcal H^{n-1}(\partial A)\).',r'If \(u\) is a solution with \(\|Du\|_\infty\le K<\infty\), then for every smooth relatively compact subdomain \(A\), \[\left|\int_AH(x,u(x))\,dx\right|\le\frac{K}{\sqrt{1+K^2}}\mathcal H^{n-1}(\partial A).\] The same statement has a finite-perimeter formulation using normal traces. The sign convention disappears after taking absolute values.','E',r'\citet[\S1B]{giusti1976boundary} treats the same geometric obstruction. The constant in the notebook is precisely the supremum norm of the flux.',(GJ,),match='exact')
item(338,'P000558','definition','Bounded variation and the dual definition of total variation',r'BV functions are \(L^1\) functions whose first distributional derivatives are Radon measures, with a dual supremum over bounded test vector fields.',r'For an open \(\Omega\), \(u\in BV(\Omega)\) means \(u\in L^1(\Omega)\) and \[|Du|(\Omega)=\sup_{g\in C_c^1(\Omega;\mathbb R^n),\ |g|\le1}\int_\Omega u\operatorname{div}g\,dx<\infty.\] This is equivalent to the distributional gradient being a finite vector Radon measure.','E',r'\citet[\S1A]{giusti1976boundary} recalls the standard definition used in the earlier area-relaxation theory.',(GJ,),literal='correct',match='exact')
item(338,'P000558','definition','Relaxed area for a BV graph',r'The notation \(\int\sqrt{1+|Du|^2}\) is defined through a supremum over \((g_0,g)\) satisfying \(g_0^2+|g|^2\le1\).',r'If \(Du=\nabla u\,dx+D^su\), the relaxed area is \[\mathcal A(u)=\int_\Omega\sqrt{1+|\nabla u|^2}\,dx+|D^su|(\Omega).\] It equals \(\sup\int_\Omega(g_0+u\operatorname{div}g)\,dx\) over compactly supported \(C^1\) test fields with \(g_0^2+|g|^2\le1\). It is not obtained by squaring a singular measure as a density.','E',r'\citet[\S1A]{giusti1976boundary} gives this generalized-area formulation; the notebook\textquotesingle s dual definition is the appropriate interpretation.',(GJ,),literal='correct',match='exact')
item(338,'P000558','theorem','Lower semicontinuity of BV area',r'The area is lower semicontinuous for \(L^1\) convergence.',r'If \(u_j\to u\) in \(L^1(\Omega)\), then \(\mathcal A(u)\le\liminf_j\mathcal A(u_j)\), with the area extended by \(+\infty\) outside \(BV\). Each functional in the dual supremum is \(L^1\)-continuous, and a supremum of such functions is lower semicontinuous.','E',r'\citet[\S1A]{giusti1976boundary} uses this standard direct-method fact. The dual formula in the notes supplies its proof.',(GJ,),literal='correct',match='exact')
item(338,'P000558','theorem','Compactness of bounded BV sets',r'Bounded sets in BV are said to be relatively compact in \(L^1\).',r'If \(\Omega\) is bounded with Lipschitz boundary and \(\sup_j(\|u_j\|_{L^1}+|Du_j|(\Omega))<\infty\), there is an \(L^1(\Omega)\)-convergent subsequence. On a general open set only local compactness follows without control at infinity and the boundary. Bounding total variation alone does not control additive constants.','E',r'\citet[\S1A]{giusti1976boundary} states the bounded-domain framework in which the BV compactness argument is applied.',(GJ,),reconstruction=r'The domain condition and the full BV norm are essential additions.',match='exact')
item(338,'P000558','construction','Boundary mismatch in the relaxed Dirichlet functional',r'The area-plus-potential expression acquires \(\int_{\partial\Omega}|u-\phi|\,d\mathcal H^{n-1}\).',r'For a bounded Lipschitz domain, BV trace \(Tu\) and integrable boundary datum \(\phi\), the generalized Dirichlet energy contains \[\mathcal A(u)+\int_\Omega\lambda(x,u)\,dx+\int_{\partial\Omega}|Tu-\phi|\,d\mathcal H^{n-1}.\] This boundary term permits detachment from the prescribed trace while charging its vertical area. Existence still requires lower semicontinuity and coercivity of the entire functional.','E',r'\citet[pp.~501--505]{giusti1976boundary} explicitly recalls generalized-solution constructions from Giusti (1970), Giaquinta and Miranda (1973--1974). This framework was already available at the talk; the 1976 paper studies its boundary behaviour.',(GJ,),match='exact')
correction('P000557','changed one-dimensional left endpoint',r'\(u(-1)=3,\ u(1)=3+A\)',r'\(u(-1)=-3,\ u(1)=3+A\) for the subsequent argument','The handwritten plus sign is faithfully transcribed, but the next integral starts from -3 and compares with 3 cube-root(x).')
correction('P000557','integrated prescribed flux',r'\(u^{\prime}/\sqrt{1+(u^{\prime})^2}=(1+x^{4/3})^{-1/2}\)',r'Add an integration constant C before comparing boundary data','Different solutions of the same prescribed derivative of the flux differ by a constant in the flux. The bound at zero then forces C<=0.')
correction('P000556-P000557','mean-curvature sign convention',r'\(\operatorname{div}(Du/W)=-H\), but \(F=\int W+\lambda\), \(\lambda_t=H\)',r'The displayed functional yields div(Du/W)=H; change one sign consistently','Direct differentiation of the functional fixes the Euler--Lagrange sign.')
correction('P000558','BV compactness','Bounded BV sets are relatively compact in L1','Use the full BV norm on a bounded Lipschitz domain, or state local compactness','Unbounded domains admit escaping translates; total variation alone does not bound constants.')

talk(339,'1974-09-09','B. A. Dubrovin','P000558','Finite-gap Bloch functions and their divisor',r'This short continuation constructs the hyperelliptic spectral surface and locates the poles and zeros of a normalized Bloch solution. The real gap ovals are visible in the drawing. The divisor statement must allow cancellations, especially at the normalization point where the function equals one. The next dated lecture starts on P000559.')
item(339,'P000558','construction','The finite-gap hyperelliptic spectral curve',r'For a finite-gap potential, \(R(E)=\prod(E-E_i)\) and \(\Gamma_N\) is the surface of \(\sqrt{R(E)}\); \(N\) is its genus.',r'For a real smooth periodic Schrödinger potential with exactly \(N\) open gaps, list the distinct finite band endpoints \(E_1<\cdots<E_{2N+1}\). The smooth compactification of \(y^2=\prod_{j=1}^{2N+1}(E-E_j)\) has genus \(N\). Closed gaps are omitted after normalization.','A',r'\citet[\S3]{dubrovinnovikov1974periodicity} gives the algebraic spectral construction (received June 1974, published 1974). The hyperelliptic genus count itself is classical.',(DN,),match='exact')
item(339,'P000558','theorem','Meromorphic continuation of the normalized Bloch solution',r'Bloch functions continue analytically, corrected to meromorphically, on \(\Gamma_N\setminus\{\infty\}\).',r'With \(\Psi(x_0,E,x_0)=1\), the finite-gap Bloch solution at fixed \(x\) is meromorphic on the spectral curve away from the point above infinity. In the local parameter \(k=\sqrt E\), its exponential factor is \(e^{\pm ik(x-x_0)}\); infinity is generally an essential singularity.','A',r'\citet[\S3]{dubrovinnovikov1974periodicity} states the continuation result; \citet[\S\S1--2]{dubrovinnovikov1974periodic} develops the eigenfunction construction (submitted July 1974, Russian publication December 1974).',(DN,JETP),match='exact')
item(339,'P000558','claim','Pole and zero divisors of degree N with possible cancellation',r'The function is said to have \(N\) poles \(\gamma_i(x_0)\) and \(N\) zeros.',r'There are effective degree-\(N\) divisors \(D(x_0)\) and \(D(x)\) such that the finite divisor of the normalized solution is \(D(x)-D(x_0)\), with common points cancelling. Generically the poles and zeros each number \(N\), with multiplicity; at \(x=x_0\), \(\Psi\equiv1\) and all cancel.','A',r'The divisor construction is in \citet[\S3]{dubrovinnovikov1974periodicity}. The cancellation qualification follows already from the normalization and prevents a false universal exact count.',(DN,),literal='correct with missing hypotheses',match='exact')
item(339,'P000558','claim','One divisor point on each real gap oval',r'Each oval projects to a forbidden gap and carries one pole and one zero; poles depend on \(x_0\).',r'For the real nonsingular finite-gap class, each admissible Dirichlet divisor has one point on each real oval above a closed finite gap interval, with its sheet specified and the two sheets meeting at endpoints. \(D(x_0)\) is the pole divisor and \(D(x)\) the moving zero divisor before cancellation.','A',r'\citet[\S3, the points \(\gamma_j\)]{dubrovinnovikov1974periodicity} gives the gap and sheet description; \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} supplies its detailed spectral formulation.',(DN,DMN),reconstruction=r'The assertion concerns admissible real data, not arbitrary complex divisors.',match='exact')
correction('P000558','number of Bloch poles and zeros','Has N poles and N zeros','Degree-N moving and reference divisors, with common points cancelled','At x=x0 the normalized Bloch solution is identically one. A literal uncancelled count cannot hold there.')

talk(340,'1974-09-16','B. A. Dubrovin; I. M. Gelfand (questions)','P000559-P000563','Floquet theory and the polynomial finite-gap representation',r'The lecture derives the monodromy criterion for bands, states the finite-gap/stationary-KdV correspondence and Jacobian description, and expresses the logarithmic derivative of a Bloch function through a polynomial divisor. The proof sketch needs several repairs: a missing subtraction in the monodromy formula, a Wronskian factor, an infinity exponent, and a global complex-growth step in the polynomiality argument. The final variational equation describes stationary members of the hierarchy.')
item(340,'P000559','definition','Periodic Schrödinger bands and finite-gap potentials',r'The spectrum of \(L=-d^2/dx^2+u(x)\), \(u(x+T)=u(x)\), is a union of intervals; finitely many bands is called finite-zone.',r'For real smooth \(T\)-periodic \(u\), the self-adjoint operator on \(L^2(\mathbb R)\) has a closed band spectrum. A finite-gap potential has finitely many open bounded gaps, so its spectrum consists of finitely many compact bands and a final half-line, with closed gaps filled in.','E',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} recalls this classical spectral setting before describing the 1974 finite-gap theory.',(DMN,),match='exact')
item(340,'P000559','construction','Unimodular monodromy and its characteristic equation',r'Translation by \(T\) acts on a solution basis through \(\widehat T=(\alpha_{ij})\); the Wronskian gives determinant one.',r'For \(-y^{\prime\prime}+uy=Ey\), a fundamental solution matrix normalized at \(x_0\) has monodromy \(M(E,x_0)\in\operatorname{SL}_2(\mathbb C)\). If \(\tau=\tfrac12\operatorname{tr}M\), its multipliers satisfy \(\lambda^2-2\tau\lambda+1=0\). The determinant is one because the Wronskian is constant.','E',r'\citet[Ch.~II, \S1, monodromy construction]{dubrovinmatveevnovikov1976nonlinear} records these classical identities.',(DMN,),literal='correct',match='exact')
item(340,'P000559-P000560','theorem','The bounded-solution and discriminant criterion for the spectrum',r'A spectral point has a bounded solution, hence a monodromy eigenvalue of modulus one; \(|\operatorname{tr}M|<2\) gives complex roots and \(>2\) real roots.',r'For real \(E\), \(E\in\sigma(L)\) if and only if \(|\tau(E)|\le1\), equivalently there is a nonzero solution bounded on all of \(\mathbb R\). In band interiors the multipliers are conjugate on the unit circle; in open gaps they are distinct real reciprocals. At an endpoint a bounded periodic or antiperiodic solution exists even when a second solution grows linearly.','E',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} gives the Floquet spectral criterion. The endpoint qualification distinguishes one bounded eigenvector from boundedness of every monodromy iterate.',(DMN,),match='exact')
item(340,'P000560','definition','Quasimomentum and the Bloch multiplier',r'The Bloch condition is written using \(u\), with \(\nu=e^{ip}\) and \(p\) called quasimomentum.',r'For a Bloch solution \(\psi\), write \(\psi(x+T,E)=e^{ip(E)}\psi(x,E)\). The phase \(p\) is defined modulo \(2\pi\) and a choice of the reciprocal multiplier; on spectral bands it can be chosen real. The symbol \(u\) in that line denotes the eigenfunction, although elsewhere it denotes the potential.','E',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} fixes the same Floquet phase convention, subject to a possible factor \(T\).',(DMN,),match='exact')
item(340,'P000560','claim','Base-point independence of the discriminant',r'The half-trace \(\tau(E)\) does not depend on the normalization point \(x_0\).',r'Monodromy matrices at different base points are conjugate by the intervening fundamental solution matrix. Their trace and multipliers are therefore independent of \(x_0\), although the individual matrix entries and normalized eigenvectors are not.','E',r'This standard conjugacy argument underlies \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear}.',(DMN,),literal='correct',match='exact')
item(340,'P000560','theorem','Bloch continuation to the finite-gap curve',r'Theorem 1 says that Bloch eigenfunctions analytically continue to \(\Gamma_N\), with normalization one at \(x_0\).',r'For a real nonsingular finite-gap potential, the normalized Bloch function extends meromorphically to \(\Gamma_N\setminus\{\infty\}\), with fixed pole divisor and an essential exponential singularity at infinity. ``Analytic continuation'' is not a claim of holomorphy at its poles or at infinity.','A',r'\citet[\S3]{dubrovinnovikov1974periodicity} is the matching 1974 result; this repeats items 1974-339.2--4 in a longer proof-oriented lecture.',(DN,),match='exact')
item(340,'P000560','theorem','Finite-gap potentials are stationary for a higher KdV equation',r'Theorem 0 states that every finite-zone potential is a stationary solution of a higher KdV equation.',r'For a real smooth periodic Schrödinger potential, having finitely many open gaps is equivalent to satisfying a nontrivial stationary equation in the KdV hierarchy, allowing a finite linear combination of the flows and integration constants. Equivalently, there is an odd-order differential operator commuting with \(L\) of the corresponding finite-gap type.','A',r'\citet[\S2 and the converse at the end of \S3]{dubrovinnovikov1974periodicity} gives both directions, referring the stationary-to-finite-gap direction to \citet{novikov1974periodic}. Novikov\textquotesingle s paper was received February 1974; the joint paper June 1974; both appeared in 1974. Earlier related occurrence: 1973-326.15.',(DN,NV),match='exact',problem='GP-1974-10')
item(340,'P000560','theorem','The Jacobian description of the isospectral manifold',r'Theorem 2 calls the set of potentials with fixed spectrum \(J(\Gamma_N)\).',r'For a fixed nonsingular finite-gap curve, admissible real divisor data identify the smooth real isospectral family with a real \(N\)-torus. Complex divisor coordinates identify an open part of the complexified construction with an open part of \(J(\Gamma_N)\), whose compactification is the Jacobian.','A',r'\citet[\S3]{dubrovinnovikov1974periodicity} supplies the algebraic-geometric identification. The real/complex and affine/compact distinctions refine the lecture\textquotesingle s shorthand.',(DN,),match='exact')
item(340,'P000560','claim','Higher KdV flows on the isospectral Jacobian',r'KdV and its higher analogues act on the fixed-spectrum manifold.',r'The commuting hierarchy flows preserve the spectral curve and become constant-velocity translations in Abel coordinates on its Jacobian. On the admissible real component these are commuting flows on a real torus; periodicity in a particular time requires additional rationality of the velocity vector.','A',r'\citet[\S3, Abel coordinates]{dubrovinnovikov1974periodicity} and \citet[\S\S2--3]{dubrovinnovikov1974periodic} identify these flows (1974 submissions and publications).',(DN,JETP),match='exact')
item(340,'P000560','claim','Monotonicity of a chosen band phase',r'The roots are said to run in one direction, with a parenthetical remark that this can be proved.',r'On the interior of a spectral band, choose the Bloch branch with positive conserved current \(j=\operatorname{Im}(\overline\psi\psi^{\prime})\). Its phase satisfies \(p^{\prime}(E)=(2j)^{-1}\int_{x_0}^{x_0+T}|\psi|^2dx>0\). The reciprocal multiplier travels in the opposite angular direction. Thus the two roots cannot both be said to rotate in the same direction without a branch convention.','E',r'The discriminant and phase theory is classical; compare \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear}. The phase derivative identity is obtained by differentiating the differential equation and its Floquet boundary condition.',(DMN,),reconstruction=r'The specific monotonicity statement and current orientation are a reconstruction of the terse sentence.',match='partial',confidence='medium')
item(340,'P000560','remark','The physical trapping and exponential-decay shorthand',r'The physical sketch contrasts transmission with trapping; a nearby fragment says that forbidden zones decay exponentially.',r'In an open gap the two Bloch solutions grow and decay exponentially in opposite spatial directions; neither is a nonzero solution decaying at both infinities for the unperturbed periodic operator. If the fragment instead refers to the widths of high-energy gaps, an exponential estimate needs regularity assumptions beyond the written periodicity. The notes do not identify which decay is intended.','F',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} supplies the first Floquet interpretation. No exact assertion about gap-width asymptotics or a localized particle state can be recovered from this fragment.',(DMN,),literal='not determinable',match='thematic only',development='none',confidence='low')
item(340,'P000560-P000561','claim','Extrema of the discriminant and the sign of the lower bound',r'The graph is said to have infinitely many maxima and minima, with both written as \(\ge1\).',r'For a real periodic scalar Schrödinger operator, real critical points of the discriminant lie outside open band interiors. Its successive maxima satisfy \(\tau\ge1\) and minima satisfy \(\tau\le-1\), allowing equality at closed gaps. High-energy asymptotics yield infinitely many such extrema.','E',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} gives the standard discriminant picture. The source drawing itself puts minima below \(-1\), confirming that the verbal inequality needs a sign or absolute value.',(DMN,),literal='false as written',match='exact')
item(340,'P000561-P000562','claim','Open band edges, closed gaps and monodromy Jordan form',r'One selects simple roots of \(\tau(E)=\pm1\) for band endpoints; these give Jordan cells, while a diagonal matrix is degenerate.',r'At an endpoint of an open gap, \(\tau^2-1\) has a simple zero and monodromy has a nontrivial Jordan block with eigenvalue \(+1\) or \(-1\). At a closed gap, the zero is double and \(M=\pm I\). Removing these double points gives the finite-gap curve. This concerns a real self-adjoint scalar periodic equation.','E',r'\citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} explains the scalar Floquet alternative. The notebook\textquotesingle s reference to Gelfand--Lidskii (1955) is broader; no exact claim from that paper is substituted here.',(DMN,),match='exact')
item(340,'P000561','construction','The normalization-independent Riccati variable',r'The logarithmic derivative is \(\chi=-i\Psi^{\prime}/\Psi\); it does not depend on \(x_0\), is periodic in \(x\), and satisfies a Riccati equation.',r'On a fixed Bloch branch, away from zeros of \(\Psi\), multiplication by an \(x\)-independent normalization cancels in \(\chi\). Floquet periodicity gives \(\chi(x+T,E)=\chi(x,E)\), and substitution in \(L\Psi=E\Psi\) gives \(-i\chi_x+\chi^2+u-E=0\). The identities extend meromorphically across the divisor.','E',r'The Riccati construction and its role in conserved densities are recalled in \citet[\S2]{dubrovinnovikov1974periodicity}; the substitution itself is elementary.',(DN,),literal='correct',match='exact')
item(340,'P000561','claim','Amplitude, phase and the real part of the Riccati variable',r'The formulas are \(\chi_I=\tfrac12\chi_{R,x}/\chi_R\), \(|\Psi|^2=\chi_R(x_0)/\chi_R(x)\), and \(p=\int_0^T\chi_Rdx\) up to a phase integer.',r'For real \(E\) in a band interior, choose a branch with nonzero current. Separating the Riccati equation yields \(\chi_I=\tfrac12(\log|\chi_R|)_x\). Consequently \[\Psi(x)=\sqrt{\frac{\chi_R(x_0)}{\chi_R(x)}}\exp\!\left(i\int_{x_0}^x\chi_R(s)ds\right).\] The positive amplitude ratio is periodic, so \(p=\int_{x_0}^{x_0+T}\chi_Rdx\pmod{2\pi}\).','E',r'\citet[\S3]{dubrovinnovikov1974periodicity} uses the amplitude-phase factorization. The source\textquotesingle s overwritten factor before \(\pi n\) is not recoverable; the multiplier fixes the modulus \(2\pi\).',(DN,),reconstruction=r'The relation between real and imaginary parts applies on real bands, not literally to arbitrary complex \(E\).',match='exact')
item(340,'P000561-P000563','method','The high-energy Riccati expansion and local differential polynomials',r'An expansion \(\chi\sim k+\sum_{m\ge1}\chi_m(x)/(2k)^m\), \(k=\sqrt E\), is obtained from the Riccati equation; the real part contains odd-index terms.',r'For a smooth potential, the formal recursion is \(\chi_1=-u\), \(\chi_{m+1}=i\partial_x\chi_m-\sum_{a+b=m}\chi_a\chi_b\). Thus \(\chi_2=-iu_x\) and \(\chi_3=u_{xx}-u^2\). Odd coefficients are real and even coefficients imaginary for real \(u\). The corresponding analytic high-energy expansion is asymptotic in suitable complex sectors; convergence of the infinite series is not asserted.','E',r'\citet[\S2]{dubrovinnovikov1974periodicity} records the recursion framework underlying the higher KdV integrals. The displayed first coefficients are checked directly from the notebook\textquotesingle s convention.',(DN,),match='exact')
item(340,'P000561','claim','The monodromy formula and the missing subtraction',r'Formula (1) has \(\sqrt{1-\tau^2}/\alpha_{21}\) plus \((i/2)\alpha_{11}\alpha_{22}/\alpha_{21}\), with no visible operator between the two diagonal entries.',r'With the row convention \(c(x+T)=a_{11}c(x)+a_{12}s(x)\), \(s(x+T)=a_{21}c(x)+a_{22}s(x)\), and multiplier \(\mu=\tau+i\sqrt{1-\tau^2}\), one has \[\chi(x_0,E)=\frac{\sqrt{1-\tau^2}}{a_{21}}+\frac i2\frac{a_{11}-a_{22}}{a_{21}}.\] Indeed \(\Psi=c+i\chi s\) gives \(\mu=a_{11}+i\chi a_{21}\). The formula is meromorphic where the denominator vanishes.','E',r'This is direct two-dimensional eigenvector algebra consistent with \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear}. The required subtraction is a mathematical reconstruction, not a confidently identified hidden stroke.',(DMN,),literal='false as written',match='exact')
item(340,'P000562','claim','The Wronskian normalization at the base point',r'The line reads \(\{c,\Psi\}|_{x_0}=i\Psi^{\prime}(x_0)=i\chi(x_0)\), with an overwritten middle symbol.',r'Using \(W(c,\Psi)=c\Psi^{\prime}-c^{\prime}\Psi\), \(c(x_0)=1,c^{\prime}(x_0)=0,\Psi(x_0)=1\), the correct identity is \(W(c,\Psi)=\Psi^{\prime}(x_0)=i\chi(x_0)\). The extra factor \(i\) before \(\Psi^{\prime}\) is inconsistent with these definitions.','E',r'The check uses the preceding normalization and Wronskian constancy, the same standard construction as \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear}.',(DMN,),reconstruction=r'The overwritten glyph remains palaeographically uncertain; only the mathematical identity is fixed.',literal='false as written',match='exact')
item(340,'P000562','construction','Cancelling the closed-gap entire factor',r'The notes divide \(a_{21}\) by \(\sqrt{(1-\tau^2)/R}\), asserting that the quotient is entire.',r'In the finite-gap real periodic case, the zeros of \(1-\tau^2\) not included in \(R\) are precisely the closed-gap double zeros. Therefore \((1-\tau^2)/R\) has an entire square root \(H(E)\), up to sign, and \(a_{21}\) vanishes at its zeros. Division removes those simple zeros and gives an entire function \(P=a_{21}/H\).','A',r'The finite-gap reduction is developed in \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear} and announced in \citet[\S3]{dubrovinnovikov1974periodicity}.',(DMN,DN),reconstruction=r'The multiplicities and removability are needed; a bare quotient of two entire functions need not be entire.',match='exact')
item(340,'P000562','claim','Why the reduced entire function is a polynomial',r'From \(\chi_R\sim k\) and the leading power of \(\sqrt R\), the notes conclude that the reduced function is a polynomial in \(E\).',r'The conclusion requires complex growth control in addition to removability. If an entire \(P\) satisfies a global bound \(|P(E)|\le C(1+|E|)^N\), Cauchy estimates give \(\deg P\le N\); the leading normalization then gives degree \(N\). Asymptotics on the positive real axis alone do not imply this: \(E^N+e^{-E}\) has the same leading behaviour there and is not a polynomial.','A',r'The established finite-gap polynomial conclusion is in \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear}. The notebook omits the sectorial estimates and their global complex-analytic use; the elementary implication above audits that gap in the sketch.',(DMN,),reconstruction=r'The global polynomial bound is a sufficient editorial reconstruction, not a hypothesis visibly stated in the notes or a proof that the notes supplied it.',literal='correct with missing hypotheses',match='partial')
item(340,'P000562','construction','The polynomial representation of the Riccati variable',r'The final formulas are \(\chi_R=\sqrt R/P\), \(P=\prod(E-\gamma_i(x))\), and \(\chi=(\sqrt R-iP_x/2)/P\).',r'For the nonsingular finite-gap construction, the monic degree-\(N\) divisor polynomial \(P(E,x)\) gives \[\chi=\frac{\sqrt{R(E)}-\frac i2P_x(E,x)}{P(E,x)}.\] Compatibility with the Schrödinger equation is the identity \[R=(E-u)P^2+\tfrac12PP_{xx}-\tfrac14P_x^2,\] and its derivative yields \(P_{xxx}-4(u-E)P_x-2u_xP=0\). The notation \(\chi_R\) away from real bands means analytic continuation, not the nonholomorphic operation of taking a real part.','A',r'\citet[\S3]{dubrovinnovikov1974periodicity} and \citet[Ch.~II]{dubrovinmatveevnovikov1976nonlinear} supply the classical finite-gap formula. The companion\textquotesingle s separate compatibility audit expands the identity directly.',(DN,DMN),match='exact')
item(340,'P000562','claim','The leading power of the spectral square root',r'The line gives \(\sqrt{R(E)}\sim E^N\), while the next numerator is \(kE^N\).',r'Since \(R\) is monic of degree \(2N+1\), one has \(\sqrt{R(E)}\sim E^{N+1/2}=kE^N\) on a chosen sectorial square-root branch. Division by a monic degree-\(N\) polynomial then gives \(\chi_R\sim k\).','E',r'The correction follows from the degree of the polynomial written in the notes and agrees with \citet[\S3]{dubrovinnovikov1974periodicity}.',(DN,),literal='false as written',match='exact')
item(340,'P000562-P000563','construction','Conserved Riccati integrals and the stationary variational equation',r'The integrals \(I_n[u]=\int_0^T\chi_{2n+3}(x)dx\) are introduced, followed by \(\delta(\sum c_nI_n)/\delta u=d\).',r'For smooth periodic \(u\), the odd Riccati densities integrate to local conserved functionals of the KdV hierarchy, up to normalization and total derivatives. A stationary linear combination of flows \(u_t=\partial_x\delta(\sum c_nI_n)/\delta u\) satisfies \(\delta(\sum c_nI_n)/\delta u=d\), where the sum is finite and \(d\) is a spatial constant.','A',r'\citet[\S2]{dubrovinnovikov1974periodicity} gives the same variational stationary construction and attributes its finite-dimensional integrability to \citet{novikov1974periodic}; both are 1974 publications.',(DN,NV),match='exact')
item(340,'P000563','claim','The derivative order of the Riccati densities',r'The odd coefficient is written \(\chi_{2n+1}=Q(u,u^{\prime},\ldots,u^{(n-1)})\).',r'Before integrating by parts, \(\chi_{2n+1}\) generally contains derivatives through order \(2n\). Its leading linear term is \((-1)^{n+1}u^{(2n)}\); already \(\chi_3=u_{xx}-u^2\) contradicts the written order. Integrated densities may be replaced by lower-order representatives modulo total derivatives, but that is a different statement.','E',r'The recursion in item 1974-340.16 verifies the correction directly; compare the density construction of \citet[\S2]{dubrovinnovikov1974periodicity}. The doubtful exponent is retained in the source transcription and emended only mathematically.',(DN,),literal='false as written',match='exact')
correction('P000560','Bloch equation uses potential symbol',r'\(u(x+T)=\nu u(x)\)',r'Use \(\psi\) for the Bloch eigenfunction','The same page has already reserved u for a periodic potential; the multiplier equation is for an eigenfunction.','ambiguity')
correction('P000560-P000561','discriminant extrema','max and min >= 1','maxima >= 1; minima <= -1, or absolute values >= 1','The drawing puts the lower extrema below -1. The real scalar Floquet theorem has the stated opposite signs.')
correction('P000561','monodromy numerator',r'\(a_{11}a_{22}\)',r'\(a_{11}-a_{22}\)','No intervening operator is distinguishable in the scan. The normalized eigenvector identity mu=a11+i chi a21 requires the difference.','ambiguity')
correction('P000561','phase integer',r'\(p=\int\chi_R+\pi n\), overwritten coefficient',r'\(p=\int\chi_R\pmod{2\pi}\)','The multiplier is exp(i p); its logarithm is defined modulo 2 pi. The preceding amplitude is positive and periodic on a real band.','ambiguity')
correction('P000562','Wronskian factor',r'\(W(c,\Psi)=i\Psi^{\prime}(x_0)=i\chi(x_0)\)',r'\(W(c,\Psi)=\Psi^{\prime}(x_0)=i\chi(x_0)\)','The middle handwritten symbol is overwritten. The formula follows from c=1,cprime=0 and chi=-i Psiprime/Psi.','ambiguity')
correction('P000562','growth at infinity',r'\(\sqrt R\sim E^N\)',r'\(\sqrt R\sim E^{N+1/2}=kE^N\)',r'\(R\) has degree \(2N+1\), and the next source line already contains \(kE^N\).')
correction('P000562','polynomiality implication','Real-axis asymptotic implies entire function is polynomial','Supply global polynomial growth, obtained through the appropriate complex estimates',r'An entire \(E^N+\exp(-E)\) has the same leading asymptotic on the positive real axis but is not a polynomial.','ambiguity')
correction('P000563','Riccati coefficient derivative order',r'\(\chi_{2n+1}=Q(u,\ldots,u^{(n-1)})\)',r'Before integration by parts the maximum derivative order is \(2n\)',r'The recurrence gives \(\chi_3=u_{xx}-u^2\). The source exponent \(n-1\) is itself palaeographically provisional.','ambiguity')

talk(341,'1974-09-23','Enrico Giusti; I. M. Gelfand (intervention)','P000564-P000565','Singular weak solutions and partial regularity of elliptic systems',r'Giusti states the energy formulation, contrasts scalar and two-dimensional regularity with vectorial counterexamples, and gives an analytic coefficient tensor for the singular map \(x/|x|\). The first coefficient in the copied tensor is incompatible with that solution; an exact residual and a repaired uniformly elliptic tensor are proved in the audit. The discussion ends with a variational-existence question and Gelfand\textquotesingle s unspecified proposal for an analogue of Hironaka resolution. The dilogarithm material above Giusti\textquotesingle s heading belongs to record 342.')
item(341,'P000564-P000565','definition','The energy weak formulation of a quasilinear system',r'The weak equation sums \(a_{ij}^{hk}(x,u)D_i u^hD_j\varphi^k\); the following strong equation instead writes \(D_i u^k\) inside the sum over \(h\).',r'For \(u\in W^{1,2}_{\mathrm{loc}}(\Omega;\mathbb R^N)\), bounded coefficients and compactly supported smooth tests, the weak system is \[\sum_{i,j,h,k}\int_\Omega a_{ij}^{hk}(x,u)D_i u^hD_j\varphi^k\,dx=0.\] It is equivalent to \(\sum_{i,j,h}D_j(a_{ij}^{hk}(x,u)D_i u^h)=0\) in distributions for each \(k\). Here \(D_i=\partial/\partial x_i\), and the unknown argument lies in \(\mathbb R^N\).','E',r'\citet[\S3.2, equation (3.5)]{mingione2006regularity} uses the same energy-system formulation. The repeated component index in the strong equation is a correctable mismatch with the preceding weak form.',(MG,),literal='false as written',match='exact')
item(341,'P000564-P000565','definition','Strong ellipticity and the distinction from coefficient smoothness',r'The displayed quadratic form is bounded below by \(|\xi|^2\).',r'The relevant system assumption is \(\sum a_{ij}^{hk}(x,v)\xi_i^h\xi_j^k\ge\nu|\xi|^2\), for all real \(N\times n\) matrices \(\xi\), together with a uniform upper bound \(|a(x,v)|\le\Lambda\). Analyticity of \(a\) as a function of \(v\) does not imply continuity of the composite \(a(x,u(x))\) if \(u\) is discontinuous.','E',r'\citet[\S3.2]{mingione2006regularity} explains exactly this mechanism in the Giusti--Miranda example. Ellipticity is an algebraic lower bound, not an automatic smoothness conclusion for systems.',(MG,),reconstruction=r'The uniform upper bound, omitted in the displayed inequality, is part of the standard energy estimates.',match='exact')
item(341,'P000565','definition','The Sobolev energy space and zero trace',r'The notes define \(W^{1,2}\) by square-integrable function and gradient and describe \(W^{1,2}_0\) as zero boundary values.',r'For an open set \(\Omega\), \(W^{1,2}(\Omega;\mathbb R^N)\) consists of functions with all first weak derivatives in \(L^2\). The space \(W_0^{1,2}\) is the closure of \(C_c^\infty\) in that norm. On a Lipschitz domain this is precisely the subspace with zero Sobolev trace.','E',r'This is the standard framework explicitly used in \citet[\S3]{mingione2006regularity}. The trace formulation needs a regular boundary, whereas the closure definition does not.',(MG,),match='exact')
item(341,'P000565','theorem','Scalar or two-dimensional regularity in the energy class',r'The cases \(N=1\) or \(n\le2\) are called regular, but the line writes \(W^{1,1}\); smooth coefficients are then said to give smooth solutions.',r'For the homogeneous second-order divergence systems under boundedness and uniform strong ellipticity, scalar energy weak solutions are locally Hölder continuous; in two dimensions the same Hölder conclusion holds for systems, using higher integrability and Sobolev embedding. The relevant class is \(W^{1,2}\). For smooth dependence on \((x,u)\), elliptic bootstrap applies on a region where the solution is already regular; it does not smooth every vectorial weak solution in higher dimensions.','E',r'\citet[\S3.1 and Theorem~4.1]{mingione2006regularity} explains the two-dimensional energy argument; \citet[pp.~28--29]{johnstara1990regularity} states the scalar and two-variable alternatives. These are classical pre-talk facts.',(MG,'johnstara1990regularity'),literal='false as written',match='exact')
item(341,'P000565','construction','The Giusti coefficient tensor and the singular radial solution',r'For \(n=N\ge3\), the first factor has coefficient \(1/(n-2)\), the second \(4/(n-2)\), and \(u(x)=x/|x|\) is claimed to solve the homogeneous system.',r'For \(A_{ij}^{hk}(v)=\delta_{ij}\delta_{hk}+(\delta_{jk}+\alpha v_jv_k/(1+|v|^2))(\delta_{ih}+\beta v_iv_h/(1+|v|^2))\), substitution gives \[\sum_{i,j,h}\partial_j(A_{ij}^{hk}(u)\partial_i u^h)=(n-1)\left(\frac{\alpha(n-2)}2-2\right)\frac{x_k}{|x|^3}.\] Thus the written \(\alpha=1/(n-2)\) fails away from the origin. Taking \(\alpha=\beta=4/(n-2)\) gives analytic bounded uniformly elliptic coefficients and a discontinuous weak solution \(u\in W^{1,2}(B_1;\mathbb R^n)\), with trace \(u=x\).','E',r'\citet[equation (3.3)]{mingione2006regularity} prints both factors with \(4/(n-2)\), attributing the construction to Giusti--Miranda (1968). The original paper was not retrieved. The exact contraction, residual, ellipticity and weak extension at zero are proved in this companion\textquotesingle s audit.',(MG,),reconstruction=r'The replacement of the first 1 by 4 is a mathematically forced reconstruction within this tensor ansatz and agrees with the later published formula. It is not a claim to have read a hidden 4 in the scan.',literal='false as written',match='partial',verification='indirect',development='annotated',status='the corrected energy-class example is verified; the literal tensor is incompatible with the stated solution.')
item(341,'P000565','claim','A three-variable, two-component counterexample without a specified system',r'The notes assert an example with \(n=3,N=2\), giving neither its coefficient formula nor a reference.',r'The exact claim depends on whether coefficients are merely measurable in \(x\), analytic in \((x,u)\), or whether lower-order quadratic gradient terms are allowed. The preceding radial map has \(N=n\) and does not itself establish the two-component case.','F',r'\citet[Theorem~3.1]{frehse2007irregular} gives a later two-real-component example in dimension three through a complex scalar equation with measurable spatial coefficients (preprint July 2007). Its discussion of the 1973 example involves a different semilinear equation. These are partial contextual matches, not verification of the same analytic homogeneous class intended here.',('frehse2007irregular',),literal='not determinable',match='partial',confidence='low',status='counterexamples in neighbouring classes are known, but the precise 1974 assertion and its coefficient class have not been identified.')
item(341,'P000565','claim','The unverified uniqueness assertion for singular Dirichlet data',r'For \(|x|=1\), \(u_i=x_i\), the notes write \(\exists!\) solution and say that it is nonregular.',r'The corrected tensor supplies at least one singular \(W^{1,2}\) solution with trace \(x\). Uniqueness among all weak solutions does not follow from positive definiteness of \(A(u)\), because the coefficient depends on the unknown. No monotonicity of the full nonlinear operator, admissible subclass or uniqueness proof is recorded.','F',r'\citet[\S3.2]{mingione2006regularity} distinguishes a variational construction from the homogeneous system. The source matching and the companion\textquotesingle s residual proof establish existence only; no exact uniqueness theorem was verified.',(MG,),literal='not determinable',match='none found',verification='unresolved lead',confidence='low',status='existence is verified for the reconstructed system; the uniqueness claim in the notebook remains unverified and is not used.')
item(341,'P000565','theorem','A relatively closed singular set of dimension strictly below n minus two',r'For continuous coefficients, the regular set \(\Omega_0\) is open, its complement \(K\) is relatively closed, \(\mathcal H^{n-2}(K)=0\), and \(\dim K<n-2\).',r'For \(n\ge3\), let \(u\in W^{1,2}_{\mathrm{loc}}(\Omega;\mathbb R^N)\) solve \(\operatorname{div}(A(x,u)Du)=0\), with bounded uniformly strongly elliptic coefficients uniformly continuous in \((x,v)\). There is an open regular set \(\Omega_u\) where \(u\) is locally Hölder of every exponent below one, and \(\dim_H(\Omega\setminus\Omega_u)<n-2\). In particular \(\mathcal H^{n-2}(K)=0\). The strict dimension statement uses more than the latter zero-measure statement alone.','E',r'\citet[\S1.1, equations (1.1)--(1.2)]{defilippismingionenowak2026partial} restates this precise classical local theorem and attributes its foundation to Giusti--Miranda and Morrey (1968). The 2025 preprint, revised July 2026, is used to verify the hypotheses and bound, not to date the original result to 2026.',('defilippismingionenowak2026partial','giusti1969partial'),reconstruction=r'Uniform bounds, uniform continuity, the energy class and the meaning of regularity are restored. The original source merely says continuous coefficients.',match='exact',verification='indirect')
item(341,'P000565','claim','The compressed higher-order partial-regularity bound',r'For order \(m>2\), the notes write \(\dim K\le n-2\).',r'The notebook does not specify whether \(m\) is the differential order or half-order, which derivatives are required to be regular, or the coefficient dependence and growth. Therefore the displayed dimension bound is not a complete theorem.','F',r'\citet[Theorems 1--2]{giusti1969partial} treats arbitrary-order quasilinear systems before the talk (received 1968; published 1969), but the opened scan did not permit a reliable exact-hypothesis comparison with this one-line bound. No specific modern higher-order theorem is substituted.',('giusti1969partial',),literal='not determinable',match='partial',verification='unresolved lead',confidence='low')
item(341,'P000565','question','Variational problems with nonregular minimizers',r'The notes ask whether there are variational problems with nonregular solutions.',r'In the broad class of vector-valued uniformly elliptic variational integrals \(\int F(x,u,Du)\), are there energy-class minimizing maps that are not continuous? Yes: analytic dependence of the quadratic coefficient tensor on \(u\) is compatible with a discontinuous local minimizer in sufficiently large dimensions. The question does not impose autonomous dependence only on \(Du\).','E',r'\citet[\S3.2, equations (3.3)--(3.4)]{mingione2006regularity} explicitly records the Giusti--Miranda 1968 variational example. Thus the broad question was already answered before this talk. Stronger later autonomous examples are not treated as an answer to an unstated restriction.',(MG,),reconstruction=r'“Solutions” is read as minimizers, the stronger variational interpretation; the distinction from merely stationary points is explicit.',literal='correct with missing hypotheses',match='exact',verification='indirect',problem='GP-1974-02')
item(341,'P000565','question','Gelfand’s proposed analogue of resolution of singularities',r'Gelfand asks for an analogue of Hironaka resolution of singularities for elliptic equations.',r'No class of equations, admissible modification, transformed unknown, or required regularity after modification is specified. Resolving analytic zero sets, desingularizing coefficients and resolving singular weak solutions are distinct possible problems. The analogy alone does not select a definite conjecture.','F',r'The partial-regularity and counterexample literature above concerns the size and occurrence of singular sets, not a universal resolution operation. Searches for an exact publication of this elliptic-resolution programme did not identify one; Hironaka\textquotesingle s algebraic theorem cannot be transferred without a specified analytic statement.',(),literal='not determinable',match='none found',verification='unresolved lead',development='none',confidence='low',speaker='I. M. Gelfand',status='the recorded programme remains insufficiently specified for a mathematical open-problem status or a claimed new solution.')
problem('GP-1974-02','Discontinuous minimizers of elliptic vectorial variational integrals',r'Do uniformly elliptic vectorial variational problems with smooth or analytic coefficient dependence admit a discontinuous energy-class minimizer?', ['1974-341.10'],r'yes, in the broad class with dependence on the unknown itself; the Giusti--Miranda example dates from 1968, as verified through \citet[\S3.2]{mingione2006regularity}. This does not assert that the repaired homogeneous PDE in the audit is its Euler--Lagrange equation or that every dimension supports the same minimizing example.',[MG])
correction('P000564','strong system component',r'\(\sum_hD_j(a_{ij}^{hk}D_i u^k)=0\)',r'\(\sum_hD_j(a_{ij}^{hk}D_i u^h)=0\)','The preceding weak form sums the h component of Du and leaves k as the equation index.')
correction('P000564','derivative index and coefficient argument',r'\(D_i=\partial/\partial x\), \(t\in\mathbb R^n\)',r'\(D_i=\partial/\partial x_i\), \(t\in\mathbb R^N\)','The system has n spatial variables and N unknown components. The literal dimensions are visible in the scan.')
correction('P000565','regularity class',r'\(u\in W^{1,1}\)',r'Use the energy class \(W^{1,2}\) for the stated uniformly elliptic system','The immediately preceding weak form and the next definition use W1,2. The standard two-dimensional regularity theorem needs its energy hypothesis.')
correction('P000565','first factor of Giusti tensor',r'\(1/(n-2)\)',r'Reconstruction: \(4/(n-2)\)',r'The scan clearly gives 1. The literal residual is \(-(3/2)(n-1)x_k/r^3\); both factors \(4/(n-2)\) make it zero and agree with Mingione (2006), equation 3.3.')
correction('P000565','Dirichlet uniqueness',r'\(\exists!\) singular solution','Existence verified after tensor correction; uniqueness is not asserted','The homogeneous-system calculation proves one weak solution only. No matching uniqueness theorem or operator monotonicity was verified.','ambiguity')

# A later source check settled the precise second-order bound, without changing
# the historical category or pretending that the original 1968 proof was read.
for o in items:
    if o['id']=='1974-335.4':
        o['statement']=r'For \(n\ge3\), bounded uniformly strongly elliptic \(A(x,v)\), uniformly continuous in \((x,v)\), and an energy weak solution of \(\operatorname{div}(A(x,u)Du)=0\), there is an open regular set on which \(u\) is locally Hölder of every exponent below one; its relatively closed complement has Hausdorff dimension strictly below \(n-2\). The assertion concerns regularity of \(u\), not an unrestricted gradient singular set.'
        o['fate']=r'\citet[\S1.1, equations (1.1)--(1.2)]{defilippismingionenowak2026partial} states the exact classical local bound and identifies its 1968 foundations. The original arbitrary-order paper \citet{giusti1969partial} was opened but its formula extraction did not permit full verification. The strict inequality is not deduced merely from zero \((n-2)\)-dimensional measure.'
        o['refs']=['defilippismingionenowak2026partial','giusti1969partial']
        o['publication_match']='exact';o['verification']='indirect';o['confidence']='high'
        o['present_status']='As of November 2026, the reconstructed second-order theorem is established; the coefficient and energy hypotheses must be retained.'
save()

# Final provenance and chronology audit: catalog aliases preserve identifiers,
# while publication dates distinguish old results from the new converse.
for t in talks:
    if t['record'] in (331,332):
        t['summary']+=r' The current-year identifiers are compatibility aliases for the five existing source occurrences 1973-331.1--4 and 1973-332.1, not newly dated mathematical occurrences. The catalogue all-links page independently retains the 1975 date; the manuscript and prior-index evidence still leave the catalogue chronology inconsistent.'
for o in items:
    if o['record'] in (331,332):
        o['reconstruction']+=(r' ' if o['reconstruction'] else '')+r'This item is a compatibility alias for the identically numbered 1973 occurrence; it is counted once when counting distinct source occurrences.'
    if o['id']=='1974-336.6':
        o['class']='E';o['refs']=list(dict.fromkeys(o['refs']+[NV]))
        o['fate']=r'\citet[\S2, equations (18)--(19), p.~64]{novikov1974periodic} already publishes the genus-two Hamiltonian construction (received 18 February 1974; publication July 1974), before this September talk. The coefficient is also \(5/8\) after expanding \citet[\S4]{dubrovinnovikov1974periodicity}. The exact bracket audit below verifies the mathematical correction in the notebook convention.'
    if o['id']=='1974-336.10':
        o['class']='E';o['refs']=[NV,DN,DMN]
        o['statement']=r'The spectral construction is established, but its coefficients depend on the Hamiltonian and spectral-coordinate normalization. With the repaired \(J_1\), canonical flow \(D_x=\{\cdot,J_1\}\), \(u=q_1\), and \(P=E^2+q_1E/2+(q_1^2-2q_2+2c)/16\), exact substitution into the squared-eigenfunction identity gives \[R=E^5+\tfrac c4E^3-\tfrac d{16}E^2+(\tfrac{J_1}{32}+\tfrac{c^2}{64})E-\tfrac{J_2}{256}-\tfrac{cd}{128}.\] This is a conditional normalization check; it does not establish a literal corrected reading of the notebook.'
        o['reconstruction']=r'The author-hosted Dubrovin--Novikov parameter change yields \(c^2/64\), but that text also prints a positive constant term and has apparent typographic defects elsewhere. The notebook does not specify its Lax matrix. The conditional computation fixes the coefficients only after the stated choices of potential, flow and divisor polynomial.'
        o['fate']=r'\citet[\S2, equation (18)]{novikov1974periodic} already publishes the genus-two spectral polynomial in July 1974. Compare \citet[\S4]{dubrovinnovikov1974periodicity} and the coordinate interpretation in \citet[Ch.~II, \S4, p.~105]{dubrovinmatveevnovikov1976nonlinear}. The companion gives an exact conditional polynomial audit, while preserving the unresolved comparison of all source normalizations.'
        o['present_status']='As of November 2026, the spectral construction is established, and the stated normalization has been checked exactly; the literal coefficient and constant-term comparison remains an explicitly unresolved normalization discrepancy.'
    if o['id']=='1974-340.23':
        o['class']='E'
        o['fate']=r'\citet[\S2, equations (6)--(8), Theorem~2.1]{novikov1974periodic} publishes the stationary variational construction and its complete integrability in July 1974, before the September talk. \citet[\S2]{dubrovinnovikov1974periodicity} recalls and attributes this result; its new converse is treated separately in item 1974-340.7.'
    if o['id']=='1974-340.10':o['problem']='GP-1973-50'
    if o['id'] in ('1974-336.15','1974-339.3','1974-339.4','1974-340.8'):o['problem']='GP-1973-51'
for crr in corrections:
    if crr['place']=='date of records 331--332':
        crr['evidence']='The scan heading unambiguously ends in74; the same five source items occur in the previous-year index. Parent verification of the MCCME all-links page confirms its1975 date, so these IDs are compatibility aliases, not new occurrences. The individual catalogue record pages could not be retrieved.'
problem('GP-1973-50','Monotonicity in a Hill spectral band',r'For a real smooth periodic one-dimensional Schrödinger operator, is the Floquet phase strictly monotone inside a band when the Bloch branch is fixed by a positive-current orientation?', ['1973-326.9','1974-340.10'],r'yes. With \(j=\operatorname{Im}(\overline\psi\psi_x)>0\), differentiation gives \(p^{\prime}(E)=(2j)^{-1}\int_{x_0}^{x_0+T}|\psi|^2dx>0\). The reciprocal branch has opposite orientation. This is classical Floquet theory; compare \citet[Ch.~II, \S1]{dubrovinmatveevnovikov1976nonlinear}.',[DMN])
problem('GP-1973-51','Supplementary data for the periodic inverse spectral problem',r'What information, in addition to periodic spectral band data, determines a periodic Schrödinger potential?', ['1973-326.13','1974-336.15','1974-339.3','1974-339.4','1974-340.8'],r'in the smooth real nonsingular finite-gap class discussed here, a suitable degree-g divisor, including the sheet choice in each closed gap interval and a fixed base point, supplies the missing phase data and parametrizes the isospectral torus. \citet[\S3]{dubrovinnovikov1974periodicity} and \citet[Ch.~II, \S3]{dubrovinmatveevnovikov1976nonlinear} verify this answer. The present occurrences do not supply a theorem for arbitrary periodic potentials with infinitely many open gaps.',[DN,DMN])
correction('P000555','spectral constant term',r'\(+J_2/256+cd/128\)',r'In the explicitly fixed audit normalization: \(-J_2/256-cd/128\); literal emendation unresolved',r'Exact polynomial expansion with \(u=q_1\) and \(P=E^2+q_1E/2+(q_1^2-2q_2+2c)/16\) forces the displayed negative sign. Available published formulas use signs whose complete normalization correspondence has not been established.','ambiguity')
save()
